export type ExcelFactorialValue = number | string;

const maxSafeInteger = BigInt(Number.MAX_SAFE_INTEGER);

export function toExcelValue(value: bigint): ExcelFactorialValue {
  if (value <= maxSafeInteger) {
    return Number(value);
  }

  return value.toString();
}

export class FactorialCache {
  private readonly cache: bigint[] = [1n];

  get size(): number {
    return this.cache.length;
  }

  extendTo(n: number): void {
    for (let i = this.cache.length; i <= n; i++) {
      this.cache.push(this.cache[i - 1] * BigInt(i));
    }
  }

  getFactorialsThrough(n: number): ExcelFactorialValue[] {
    this.extendTo(n);

    const values: ExcelFactorialValue[] = [];
    for (let i = 0; i <= n; i++) {
      values.push(toExcelValue(this.cache[i]));
    }

    return values;
  }
}
