import { FactorialCache } from "../factorial/factorial-cache";

const cache = new FactorialCache();

type WorkerRequest = {
  requestId: string;
  n: number;
};

type WorkerSuccess = {
  requestId: string;
  values: ReturnType<FactorialCache["getFactorialsThrough"]>;
};

type WorkerFailure = {
  requestId: string;
  error: string;
};

self.onmessage = (event: MessageEvent<WorkerRequest>) => {
  const { requestId, n } = event.data;

  try {
    const values = cache.getFactorialsThrough(n);
    const response: WorkerSuccess = { requestId, values };
    self.postMessage(response);
  } catch (error) {
    const message = error instanceof Error ? error.message : "Computation failed";
    const response: WorkerFailure = { requestId, error: message };
    self.postMessage(response);
  }
};
